#!/usr/bin/env python3
"""Grade 4 standalone optional-worksheet content (Project Plan item 8).

This is a NEW, separate content pipeline from data/grade4.ts (the 187-day
day-based lesson sequence) -- these worksheets are supplementary practice
material, not new lessons, and are allowed to reinforce/overlap topics
already covered across the 187 days. Grade 4 uses multiple-choice only
(mc()), matching the existing daily-quiz style, per the Kindergarten/Grade
1-vs-Grades-2-12 format split described in gen_worksheets.py.

Structure: exactly 10 worksheets per subject x 4 subjects (Language, Math,
Science, SocialStudies) = 40 worksheets, each with exactly 15 mc()
questions (60 questions per subject, 600 total). Within each subject the
10 worksheets are organized around 10 distinct practice themes/strands
spanning the grade, loosely progressing from foundational to more
advanced, so each worksheet has a clear, distinct focus. Titles are
distinct within each subject (titles may repeat across subjects).

No embedded ASCII double-quote or apostrophe characters anywhere in
title/q/option text -- contractions and possessives are dropped entirely
(e.g. "does not" not "doesnt", "the students" not "the student's"),
matching the convention used throughout the day-based curriculum scripts
(see gen_grade4_days181_187.py).

After generating, correct-answer positions are rebalanced across A/B/C/D
per subject (not just per worksheet) so there is no bias toward one
index, using the same deterministic-shuffle approach as
gen_grade4_days181_187.py's _rebalance_answer_positions helper, adapted
to the worksheet tuple shape (subject, number, title, questions) where
each question is a ('mc', q, opts, a) tuple.
"""
import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from gen_worksheets import mc, worksheet, write_worksheets


def _rebalance_answer_positions(worksheets, seed=20260820):
    """Reshuffle each mc questions option order so the correct-answer
    index is spread evenly across 0-3 within each subject, without
    changing which worksheet/question a given option set belongs to."""
    import random
    from collections import defaultdict

    by_subject = defaultdict(list)
    for w in worksheets:
        subject, number, title, questions = w
        for qi, q in enumerate(questions):
            by_subject[subject].append((w, qi))

    rng = random.Random(seed)
    for subject, entries in by_subject.items():
        n = len(entries)
        targets = [i % 4 for i in range(n)]
        rng.shuffle(targets)
        for idx, (w, qi) in enumerate(entries):
            _, _, _, questions = w
            kind, qtext, opts, a = questions[qi]
            correct_text = opts[a]
            wrong_texts = [o for j, o in enumerate(opts) if j != a]
            rng.shuffle(wrong_texts)
            target = targets[idx]
            new_opts = [None, None, None, None]
            new_opts[target] = correct_text
            wi = 0
            for slot in range(4):
                if new_opts[slot] is None:
                    new_opts[slot] = wrong_texts[wi]
                    wi += 1
            questions[qi] = (kind, qtext, new_opts, target)
    return worksheets


